package com.quizapp.security;
import java.util.*;import javax.crypto.SecretKey;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;
@Service public class JwtService {private final SecretKey key;private final long expiry;public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-ms}")long expiry){key=Keys.hmacShaKeyFor(secret.getBytes());this.expiry=expiry;}public String create(String id){return Jwts.builder().subject(id).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+expiry)).signWith(key).compact();}public String id(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}
